select.if:
WITH RECURSIVE seed_entities AS ( SELECT DISTINCT entity_id FROM chunk_entity_mention WHERE kb_id = CAST(#{kbId} AS uuid) AND chunk_id IN
CAST(#{chunkId} AS uuid)
), related_entities(entity_id, depth) AS ( SELECT entity_id, 0 FROM seed_entities UNION SELECT CASE WHEN er.source_entity_id = re.entity_id THEN er.target_entity_id ELSE er.source_entity_id END AS entity_id, re.depth + 1 FROM related_entities re JOIN entity_relation er ON er.kb_id = CAST(#{kbId} AS uuid) AND (er.source_entity_id = re.entity_id OR er.target_entity_id = re.entity_id) WHERE re.depth < #{maxHops} ), related_chunks AS ( SELECT cem.chunk_id, MIN(re.depth) AS min_depth, COUNT(*) AS matched_entities FROM related_entities re JOIN chunk_entity_mention cem ON cem.kb_id = CAST(#{kbId} AS uuid) AND cem.entity_id = re.entity_id WHERE cem.chunk_id NOT IN
CAST(#{chunkId} AS uuid)
GROUP BY cem.chunk_id ) SELECT c.id, c.kb_id, c.doc_id, c.content, c.metadata, c.embedding, c.created_at, c.updated_at FROM related_chunks rc JOIN chunk_bge_m3 c ON c.id = rc.chunk_id WHERE c.kb_id = CAST(#{kbId} AS uuid) ORDER BY rc.min_depth ASC, rc.matched_entities DESC, c.updated_at DESC LIMIT #{limit}
